from pathlib import Path
import hashlib, json
root = Path('products/services')
for folder in sorted(p for p in root.glob('*') if p.is_dir() and any(k in p.name.lower() for k in ('quebec', 'seao'))):
    for path in sorted(folder.rglob('*')):
        if path.is_file():
            payload = path.read_bytes()
            print(json.dumps({'path': str(path), 'bytes': len(payload), 'sha256': hashlib.sha256(payload).hexdigest()}))
